"""Chrome console HTML for ANNE V1 web surface."""

CONSOLE_HTML = '<!doctype html>\n<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>ANNE AI — V1</title>\n<style>\nbody{font-family:system-ui,sans-serif;max-width:980px;margin:0 auto;padding:20px;background:#f5f6f8;color:#17202a}\nmain{background:#fff;border:1px solid #ddd;border-radius:18px;padding:20px}\n#chat{height:360px;overflow:auto;border:1px solid #ddd;border-radius:12px;padding:14px;white-space:pre-wrap}\n.msg{margin:0 0 16px}.anne{background:#eef2ff;padding:10px;border-radius:10px}.user{background:#f8fafc;padding:10px;border-radius:10px}\n.badge{font-size:.75rem;border:1px solid #ccc;border-radius:999px;padding:2px 7px;margin-right:5px}\ntextarea{width:100%;box-sizing:border-box;border:1px solid #bbb;border-radius:12px;padding:12px;font:inherit;margin-top:12px}\nbutton{margin-top:10px;padding:10px 18px;border:0;border-radius:10px;cursor:pointer;background:#1d4ed8;color:#fff}\n.report{margin-top:14px;border:1px solid #ddd;border-radius:12px;padding:14px;background:#fafafa;line-height:1.45}\n.small{font-size:.9rem;color:#667085}.warn{color:#8a5a00}\n</style></head><body><main>\n<h1>ANNE AI</h1>\n<p class="small">Chrome iletişim yüzeyidir. Bilişsel kararlar ANNE runtime\'ına aittir.</p>\n<div id="chat"><div class="msg anne"><span class="badge">ANNE</span><br>Merhaba. Ben ANNE AI. Soru sorduğunuzda önceki bilgimi kontrol eder, gerekirse araştırır ve sonucu kendi değerlendirmem olarak sunarım.</div></div>\n<textarea id="prompt" rows="4" placeholder="ANNE\'ye mesaj yaz..."></textarea>\n<button id="send" type="button">Gönder</button>\n<div id="report" class="report small">Yönetici özeti burada görünecek.</div>\n</main><script>\nconst esc=s=>String(s??\'\').replaceAll(\'&\',\'&amp;\').replaceAll(\'<\',\'&lt;\').replaceAll(\'>\',\'&gt;\');\nasync function send(){\n const p=document.getElementById(\'prompt\'),c=document.getElementById(\'chat\'),rpt=document.getElementById(\'report\'),b=document.getElementById(\'send\');\n const prompt=p.value.trim(); if(!prompt) return; b.disabled=true;\n c.innerHTML+=`<div class="msg user"><span class="badge">GÖKHAN</span><br>${esc(prompt)}</div>`; p.value=\'\';\n rpt.textContent=\'ANNE bilişsel döngüyü çalıştırıyor...\';\n try{\n  const r=await fetch(\'/chat\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({prompt,actor:\'GÖKHAN\'})});\n  const d=await r.json(); if(!r.ok) throw new Error(d.detail||\'İstek başarısız\');\n  c.innerHTML+=`<div class="msg anne"><span class="badge">ANNE</span><br>${esc(d.response)}</div>`;\n  rpt.innerHTML=`<b>YÖNETİCİ ÖZETİ</b><br>${esc(d.manager_summary)}<br><br><b>EDİNİLMEK İSTENEN FAYDA</b><br>${esc(d.benefit)}<br><br><b>ÖĞRENME</b><br>${esc(d.learned)}<br><br><b>ARAŞTIRMA</b>: ${d.research_required?\'Gerekli\':\'Gerekli değil\'} — ${esc(d.research_reason||\'\')}<br><b>ÖNCEKİ BİLGİ</b>: ${d.previous_knowledge_found?\'Bulundu\':\'Yok\'}<br><b>KARŞILAŞTIRMA</b>: ${esc(d.comparison_status)}<br><b>DEĞİŞİM</b>: ${d.changed_since_previous?\'Evet\':\'Hayır\'}<br><b>DIŞ KANIT</b>: ${d.evidence_count}<br><b>GÜVEN / DURUM</b>: ${esc(String(d.confidence??\'\'))} / ${esc(d.knowledge_state||\'\')}<br><b>TECRÜBE</b>: ${esc(JSON.stringify(d.experience||{}))}`;\n  c.scrollTop=c.scrollHeight;\n }catch(e){rpt.innerHTML=\'<span class="warn">\'+esc(e.message)+\'</span>\';}\n finally{b.disabled=false;}\n}\ndocument.getElementById(\'send\').addEventListener(\'click\',send);\ndocument.getElementById(\'prompt\').addEventListener(\'keydown\',e=>{if(e.key===\'Enter\'&&(e.ctrlKey||e.metaKey)){e.preventDefault();send();}});\n</script></body></html>'
